def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number using an iterative approach.

    0-indexed: F(0) = 0, F(1) = 1, F(2) = 1, F(3) = 2, ...
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")
    if n in (0, 1):
        return n

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b
